var e={rules:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Automatize sua impressora com regras SE-ENTÃO seguras. Desativadas por padrão; você mesmo ativa cada regra.`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`Nenhuma regra ainda. Adicione uma abaixo e ative-a quando estiver pronto.`}},engine:{on:{t:0,b:{t:2,i:[{t:3}],s:`O motor de regras está LIGADO`}},off:{t:0,b:{t:2,i:[{t:3}],s:`O motor de regras está DESLIGADO`}},turnOn:{t:0,b:{t:2,i:[{t:3}],s:`Ligar`}},turnOff:{t:0,b:{t:2,i:[{t:3}],s:`Desligar`}},masterNote:{t:0,b:{t:2,i:[{t:3}],s:`Nada é executado enquanto o motor e a regra individual não estiverem ativados.`}}},triggers:{print_complete:{t:0,b:{t:2,i:[{t:3}],s:`Quando uma impressão termina`}},print_error:{t:0,b:{t:2,i:[{t:3}],s:`Quando a impressora apresenta erro`}},temp_above:{t:0,b:{t:2,i:[{t:3}],s:`Quando um aquecedor sobe acima de`}},temp_below:{t:0,b:{t:2,i:[{t:3}],s:`Quando um aquecedor cai abaixo de`}}},actions:{notify:{t:0,b:{t:2,i:[{t:3}],s:`Registrar uma notificação`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`Executar um comando g-code`}}},rule:{armed:{t:0,b:{t:2,i:[{t:3}],s:`Ativada`}},arm:{t:0,b:{t:2,i:[{t:3}],s:`Desativada`}},edit:{t:0,b:{t:2,i:[{t:3}],s:`Editar`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`Excluir`}},confirmDelete:{t:0,b:{t:2,i:[{t:3}],s:`Excluir regra`}}},form:{name:{t:0,b:{t:2,i:[{t:3}],s:`Nome da regra`}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`ex. Desligar aquecedores após a impressão`}},trigger:{t:0,b:{t:2,i:[{t:3}],s:`Se (gatilho)`}},action:{t:0,b:{t:2,i:[{t:3}],s:`Então (ação)`}},heater:{t:0,b:{t:2,i:[{t:3}],s:`Aquecedor`}},value:{t:0,b:{t:2,i:[{t:3}],s:`Temperatura (°C)`}},message:{t:0,b:{t:2,i:[{t:3}],s:`Mensagem`}},messagePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`Exibida no registro da regra`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`G-code`}},gcodePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`ex. TURN_OFF_HEATERS`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Salvar regra`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Cancelar`}},add:{t:0,b:{t:2,i:[{t:3}],s:`Adicionar uma regra`}}},log:{title:{t:0,b:{t:2,i:[{t:3}],s:`Atividade recente`}},outcome:{notify:{t:0,b:{t:2,i:[{t:3}],s:`notificado`}},ran:{t:0,b:{t:2,i:[{t:3}],s:`executou g-code`}},skipped_busy:{t:0,b:{t:2,i:[{t:3}],s:`ignorado (impressora ocupada)`}},error:{t:0,b:{t:2,i:[{t:3}],s:`erro`}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Guia`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Guia do motor de regras`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Fechar`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`O que é o motor de regras?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Ele observa a impressora e executa uma ação quando uma condição definida por você é atendida - por exemplo, registrar uma nota quando uma impressão termina ou desligar os aquecedores. Cada regra é SE (um gatilho) ENTÃO (uma ação).`}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:`Como ele se mantém seguro`}},body:{t:0,b:{t:2,i:[{t:3}],s:`O motor vem desligado por padrão e cada regra precisa ser ativada individualmente, então nada é executado de surpresa. Uma regra dispara uma vez quando sua condição se torna verdadeira pela primeira vez. As ações de g-code só são executadas com a impressora ociosa - são recusadas durante uma impressão - e todo resultado é registrado.`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Glossário`}}}},glossary:{trigger:{term:{t:0,b:{t:2,i:[{t:3}],s:`Gatilho`}},def:{t:0,b:{t:2,i:[{t:3}],s:`A condição que inicia uma regra, ex. uma impressão terminando ou um aquecedor cruzando uma temperatura.`}}},action:{term:{t:0,b:{t:2,i:[{t:3}],s:`Ação`}},def:{t:0,b:{t:2,i:[{t:3}],s:`O que a regra faz quando dispara: registrar uma notificação ou executar um comando g-code (somente com a impressora ociosa).`}}},armed:{term:{t:0,b:{t:2,i:[{t:3}],s:`Ativada`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Uma regra que está ligada. Regras desativadas são mantidas, mas nunca disparam.`}}}}}}};export{e as default};